var pluginURL = baseURL + 'vendor/tinymce/plugins/exam/';
var imageURL = pluginURL + 'img/';

tinymce.PluginManager.add('exam', function(editor, url) {
    editor.addButton('exam', {
        type: 'menubutton',
        text: 'Exam Tools',
        icon: false,
        menu: [{ 
                text: 'Multiple Choice Single Answer (MCSA)', 
                image: imageURL + 'circle.png',
                onclick: function() {
                    editor.insertContent('<a href="#" class="mce-exam-option">&nbsp;</a>');
                }
            }, { 
                text: 'Multiple Choice Multiple Answer (MCMA)',
                image: imageURL + 'square.png',
                onclick: function() {
                    name = createRandomId('check');
                    editor.insertContent('<label class="mce-exam-label"><input type="checkbox" class="mce-exam-check" name="' + name + '" id="' + name + '">&nbsp;</label>');
                }
            }, { 
                text: 'Short Answer',
                image: imageURL + 'dots.png',
                onclick: function() {
                    editor.insertContent('<input type="text" class="mce-exam-isian">');
                }
            }, { 
                text: 'Essay',
                image: imageURL + 'essay.png',
                onclick: function() {
                    editor.insertContent('<textarea class="mce-exam-uraian" rows="5">&nbsp;</textarea><p></p>');
                }
            }, { 
                text: 'True False',
                image: imageURL + 'true-false.png',
                onclick: function() {
                    name = createRandomId('radio');
                    input = '<span class="mce-exam-true-false">';
                    input += '<label class="mce-exam-label"><input type="radio" class="mce-exam-radio" name="' + name + '" value="1" id="' + name + '-1">Benar</label>';
                    input += '<label class="mce-exam-label"><input type="radio" class="mce-exam-radio" name="' + name + '" value="2" id="' + name + '-2">Salah</label>';
                    input += '</span>';

                    editor.insertContent(input);
                }
            }, { 
                text: 'Marker',
                icon: 'backcolor',
                onclick: function() {
                    input = '<span class="mce-marker">';
                    input += '<button class="mce-marker-red">Merah</button>';
                    input += '<button class="mce-marker-blue">Biru</button>';
                    input += '<button class="mce-marker-red">Hijau</button>';
                    input += '</span>';

                    editor.insertContent(input);
                    editor.insertContent('<p></p>');
                }
            }, { 
                text: 'Drag and Drop',
                image: imageURL + 'dragdrop.png',
                onclick: function() {
                    editor.windowManager.open({
                        title: 'Add Drag and Drop Box',
                        url: pluginURL + 'dragdrop',
                        width: 700,
                        height: 550,
                        buttons: [{
                            text: 'Insert',
                            onclick: function() {
                                editor.windowManager.getParams()['insert']();
                            }
                        }, {
                            text: 'Close',
                            onclick: 'close'
                        }]
                    });
                }
            }, { 
                text: 'Slider',
                image: imageURL + 'slider.png',
                onclick: function() {
                    editor.insertContent('<div class="mce-exam-slider"></div><p></p>');
                }
            }, { 
                text: 'Insert Equation',
                icon: 'charmap',
                onclick: function() {
                    editor.windowManager.open({
                        title: 'Equation',
                        url: baseURL + 'vendor/equation',
                        width: 700,
                        height: 550,
                        buttons: [{
                            text: 'Insert',
                            onclick: function() {
                                editor.windowManager.getParams()['screenShot']();
                            }
                        }, {
                            text: 'Close',
                            onclick: 'close'
                        }]
                    });
                }
            }, { 
                text: 'Insert Image',
                icon: 'image',
                onclick: function() {
                    editor.windowManager.open({
                        title: 'Insert Image',
                        url: pluginURL + 'images',
                        width: 700,
                        height: 550,
                        buttons: [{
                            text: 'Insert',
                            onclick: function() {
                                editor.windowManager.getParams()['insert']();
                            }
                        }, {
                            text: 'Close',
                            onclick: 'close'
                        }]
                    });
                }
            }, { 
                text: 'View Source Code',
                icon: 'code',
                onclick: function() {
                    editor.windowManager.open({
                        title: 'View Source Code',
                        url: pluginURL + 'beautify',
                        width: 800,
                        height: 600,
                        buttons: [{
                            text: 'Save',
                            onclick: function() {
                                editor.windowManager.getParams()['save']();
                            }
                        }, {
                            text: 'Close',
                            onclick: 'close'
                        }]
                    });
                }
            },
        ]
    });

    return {
        getMetadata: function() {
            return {
                name: "Mini Exam Plugins",
                url: "https://exam.bangunteknologi.com"
            };
        }
    };
});

function createRandomId(prefix) {
    var id = '', possible = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
    for(var i = 0; i < 5; i++) { 
        id += possible.charAt(Math.floor(Math.random() * possible.length)); 
    }
    return prefix + id;
}